  timeZone:'America/Argentina/Buenos_Aires',day:'2-digit',month:'2-digit',
  year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false
 }).formatToParts(dt);
 const get=(k:string)=>parts.find(p=>p.type===k)?.value??'';
