  if(!it||!textOk(it.description,75)||CONTACT.test(it.description)||
    typeof it.unit!=='string'||!Object.hasOwn(UNITS,it.unit))fail();
  const readable=lineaComercialLegibleMvp288(
   it.quantity,it.unit,it.description);
