-- V120 hotfix candidate: allow safe literal units, never replace a valid commercial unit with a guessed one.
DO $pre$
DECLARE f oid; d text; a aclitem[]; o oid; rec record;
 anchor text:=$old$OR v_unit IS NULL OR v_unit NOT IN
    ('unit','bag','box','kg','g','l','ml','m','m2','m3','roll','pack')$old$;
 replacement text:=$new$OR v_unit IS NULL OR char_length(v_unit) NOT BETWEEN 1 AND 80
   OR v_unit<>btrim(v_unit) OR v_unit ~ '[[:cntrl:]]'
   OR v_unit ~* '(https?://|www[.]|@|whatsapp|tel[eé]fono|celular|cuit|cuil|correo|email|raz[oó]n social|([+]?[0-9][ .-]?){9,})'$new$;
BEGIN
 FOR rec IN SELECT * FROM (VALUES
 ('public.cotironda_piloto_v2_conversation_stage(text,uuid,bigint,uuid,jsonb,text,jsonb,jsonb,jsonb,jsonb)','26ae2627ba9713556802bda634f4ff8b'),
 ('public.cotironda_piloto_v2_shadow_prepare_d013(text,text,text,text,jsonb,jsonb)','4940efa5ca78629e1cf5fdfe36c47a9e')
 ) x(sig,fp) LOOP
  f:=to_regprocedure(rec.sig); IF f IS NULL THEN RAISE EXCEPTION 'unit stage missing'; END IF;
  d:=pg_get_functiondef(f);
  IF md5(d)<>rec.fp OR (length(d)-length(replace(d,anchor,'')))/length(anchor)<>1 OR has_function_privilege('anon',f,'EXECUTE') OR has_function_privilege('authenticated',f,'EXECUTE') OR NOT has_function_privilege('service_role',f,'EXECUTE') THEN RAISE EXCEPTION 'unit stage source or ACL drift'; END IF;
  SELECT proacl,proowner INTO a,o FROM pg_proc WHERE oid=f;
  EXECUTE replace(d,anchor,replacement);
  IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=f AND proacl IS NOT DISTINCT FROM a AND proowner=o) THEN RAISE EXCEPTION 'unit stage ACL changed'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='cotironda_piloto_privado.request_lines'::regclass AND conname='request_lines_unit_check' AND pg_get_constraintdef(oid) = 'CHECK ((unit = ANY (ARRAY[''unit''::text, ''bag''::text, ''box''::text, ''kg''::text, ''g''::text, ''l''::text, ''ml''::text, ''m''::text, ''m2''::text, ''m3''::text, ''roll''::text, ''pack''::text])))') THEN RAISE EXCEPTION 'unit constraint drift'; END IF;
END $pre$;
ALTER TABLE cotironda_piloto_privado.request_lines DROP CONSTRAINT request_lines_unit_check,
 ADD CONSTRAINT request_lines_unit_check CHECK(char_length(unit) BETWEEN 1 AND 80 AND unit=btrim(unit) AND unit !~ '[[:cntrl:]]' AND unit !~* '(https?://|www[.]|@|whatsapp|tel[eé]fono|celular|cuit|cuil|correo|email|raz[oó]n social|([+]?[0-9][ .-]?){9,})');

