import assert from 'node:assert/strict';
import {cantidadUnidadSqlV2D013} from './src/domain/ia-central/puente-sql-rondas-v2-d013.ts';
import {unidadComercialSeguraV2D013,lineaComercialLegibleMvp288} from './src/domain/ia-central/fidelidad-pedido-mvp288.ts';
import {validarSnapshotPdfMvp223} from './supabase/functions/cotironda-piloto-whapi/ai-central-dispatch-mvp223.ts';
import {generarSolicitudPdfMvp091} from './supabase/functions/cotironda-piloto-whapi/request-pdf.ts';
const id='11111111-1111-4111-8111-111111111111';
const snapshot={requestId:id,city:'La Plata',deadlineIso:'2026-12-01T21:00:00Z',deliveryNote:null,requestedPayment:'efectivo',requestedVat:'No informado'};
for(const unit of ['ladrillos','pieces','placas','barras','tiras','pares','juegos','docenas','pulgadas','litros por envase','constructor','mm²','cm³','metros por rollo','a'.repeat(80)]){
 const qty='1.125'; const p=cantidadUnidadSqlV2D013(qty,unit);
 assert.ok(p,unit); assert.equal(p.cantidad,qty,unit); assert.equal(p.unidad,unit,unit);
 const item={description:'Material sintético',quantity:p.cantidad,unit:p.unidad};
 assert.equal(lineaComercialLegibleMvp288(qty,unit,item.description)?.unidad,unit);
 const validated=validarSnapshotPdfMvp223({...snapshot,items:[item]},id);
 assert.ok(validated,unit);
 const pdf=generarSolicitudPdfMvp091(validated);
 assert.ok(pdf.length>40,unit);
 assert.equal(new TextDecoder().decode(pdf.slice(0,8)),'%PDF-1.4');
}
for(const unit of ['',' ','https://x.test','a@b.test','2215551234','whatsapp','correo','teléfono','a\nb','a'.repeat(81)]){
 assert.equal(unidadComercialSeguraV2D013(unit),false,unit);
 assert.equal(cantidadUnidadSqlV2D013('3',unit),null,unit);
 assert.equal(validarSnapshotPdfMvp223({...snapshot,items:[{description:'Material sintético',quantity:'3',unit}]},id),null,unit);
}
assert.deepEqual(cantidadUnidadSqlV2D013('45','bolsas'),{cantidad:'45',unidad:'bag'});
assert.deepEqual(cantidadUnidadSqlV2D013('3','bolsones'),{cantidad:'3',unidad:'bag'});
assert.deepEqual(cantidadUnidadSqlV2D013('3','baldes'),{cantidad:'3',unidad:'unit'});
assert.deepEqual(cantidadUnidadSqlV2D013('0.001','mm'),{cantidad:'0.001',unidad:'mm'});
assert.deepEqual(cantidadUnidadSqlV2D013('2','cm'),{cantidad:'0.02',unidad:'m'});
assert.equal(cantidadUnidadSqlV2D013('0','ladrillos'),null);
assert.equal(cantidadUnidadSqlV2D013('x','ladrillos'),null);
console.log('PASS safe literal units bridge → snapshot → PDF; no network, no real messages.');

