-- One-time recovery, only for the authenticated archived incident. Run AFTER approved V121 deployment.
DO $retry$
DECLARE g cotironda_piloto_privado.v2_buyer_conversations%ROWTYPE; b text; m record; n int;
BEGIN
 SELECT p.key INTO b FROM cotironda_piloto_privado.participants p JOIN cotironda_piloto_privado.v2_buyer_conversations c ON c.buyer_key=p.key AND c.chat_hmac=p.chat_hmac
 WHERE c.id='140f6f3b-fdd9-488c-a232-9f58e4ee254b' AND p.participant_role='buyer' AND p.consent_at IS NOT NULL AND p.opted_out_at IS NULL FOR UPDATE OF p;
 IF b IS NULL THEN RAISE EXCEPTION 'unauthorized retry';END IF;
 SELECT * INTO g FROM cotironda_piloto_privado.v2_buyer_conversations WHERE id='140f6f3b-fdd9-488c-a232-9f58e4ee254b' AND buyer_key=b FOR UPDATE;
 IF g.state<>'review' OR g.revision<>1 OR g.request_id IS NOT NULL OR g.lease IS NOT NULL OR g.delivery_state<>'pending'
 OR EXISTS(SELECT 1 FROM cotironda_piloto_privado.v2_buyer_conversations c WHERE c.buyer_key=b AND c.id<>g.id AND c.state IN ('collecting','processing','sealed','awaiting_context'))
 OR EXISTS(SELECT 1 FROM cotironda_piloto_privado.v2_commercial_route_checkpoint WHERE conversation_id=g.id)
 THEN RAISE EXCEPTION 'retry already performed or conflicting conversation';END IF;
 IF (SELECT count(*) FROM cotironda_piloto_privado.v2_buyer_conversation_sources WHERE conversation_id=g.id)<>1 THEN RAISE EXCEPTION 'source count changed';END IF;
 SELECT s.message_hmac,s.source_sha256 INTO m FROM cotironda_piloto_privado.v2_buyer_conversation_sources s JOIN cotironda_piloto_privado.whapi_inbox i USING(message_hmac)
 WHERE s.conversation_id=g.id AND i.participant_key=b AND i.chat_hmac=g.chat_hmac AND s.kind='text' AND i.kind=s.kind AND i.plaintext_sha256=s.source_sha256 AND i.request_id IS NULL AND i.processing_state='needs_review' AND i.nonce_b64 IS NOT NULL AND i.ciphertext_b64 IS NOT NULL FOR UPDATE OF i;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM cotironda_piloto_privado.requests WHERE source_hmac=m.message_hmac)
 OR EXISTS(SELECT 1 FROM cotironda_piloto_privado.ai_usage_calls_mvp264 WHERE participant_key=b AND state IN ('reserved','unmetered'))
 OR (SELECT count(*) FROM cotironda_piloto_privado.ai_usage_calls_mvp264 WHERE message_hmac=m.message_hmac AND state='observed')<>2
 OR (SELECT max(call_no) FROM cotironda_piloto_privado.ai_usage_calls_mvp264 WHERE message_hmac=m.message_hmac)<>2
 THEN RAISE EXCEPTION 'source or meter conflict';END IF;
 UPDATE cotironda_piloto_privado.ai_central_attempts_mvp226 SET state='reserved',finished_at=NULL
 WHERE message_hmac=m.message_hmac AND buyer_key=b AND chat_hmac=g.chat_hmac AND source_sha256=m.source_sha256 AND state='review' AND failure_code='cantidad_unidad_no_representable_en_sql';
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'attempt changed';END IF;
 -- Keep prior failure_code until normal worker writes its new terminal outcome. Usage ledger stays intact.
 UPDATE cotironda_piloto_privado.v2_buyer_conversations SET state='collecting',revision=revision+1,ready_at=clock_timestamp() WHERE id=g.id AND revision=1 AND state='review';
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'retry race';END IF;
END $retry$;
